query AgentApproval($id: ID!) { agentApproval(id: $id) { ...AgentApprovalFields } }
fragment AgentApprovalPartContextFields on AgentApprovalPartContextModel { report { id title status claimedSeverity programId programSlug programTitle organizationName researcherUsername } program { id slug title organizationName } adjudication { id reportId severity amount currency } assignee { id username } notifications { id type title createdAt readAt } profileBefore { bio country website } payoutPreview { reportId side severity impliedSeverity cvssScore currency band { min max } derivedAmount amount amountBasis payable certificateWouldIssue awaitingCriticalReview deadlineTakeover reasoningChecked gridVersion refusal { code message } } unreadNotificationCount }
fragment AgentApprovalFields on AgentApprovalModel { id status reviewUrl clientRequestId clientDigest requiresStepUp createdAt expiresAt decidedAt consumedAt client { name } parts { index operation clientRequestId arguments irreversible audience consumedAt context { ...AgentApprovalPartContextFields } } repeatOf { id consumedAt clientName } }

mutation DecideAgentApproval($input: DecideAgentApprovalInput!) { decideAgentApproval(input: $input) { ...AgentApprovalFields } }
fragment AgentApprovalPartContextFields on AgentApprovalPartContextModel { report { id title status claimedSeverity programId programSlug programTitle organizationName researcherUsername } program { id slug title organizationName } adjudication { id reportId severity amount currency } assignee { id username } notifications { id type title createdAt readAt } profileBefore { bio country website } payoutPreview { reportId side severity impliedSeverity cvssScore currency band { min max } derivedAmount amount amountBasis payable certificateWouldIssue awaitingCriticalReview deadlineTakeover reasoningChecked gridVersion refusal { code message } } unreadNotificationCount }
fragment AgentApprovalFields on AgentApprovalModel { id status reviewUrl clientRequestId clientDigest requiresStepUp createdAt expiresAt decidedAt consumedAt client { name } parts { index operation clientRequestId arguments irreversible audience consumedAt context { ...AgentApprovalPartContextFields } } repeatOf { id consumedAt clientName } }

query GetAdminPrograms($filters: ProgramFilterInput, $skip: Int, $take: Int) { adminPrograms(filters: $filters, skip: $skip, take: $take) { ...ProgramCardFields } }
fragment OrganizationSummaryFields on ProgramOrganizationModel { id name slug }
fragment ProgramCardFields on ProgramModel { currency id organizationId organization { ...OrganizationSummaryFields } title slug description contentLocale scope rules status visibility rewardGrid rewardRange { min max currency } triageDeadlineBusinessDays startDate endDate createdAt }

query GetMyPrograms($skip: Int, $take: Int) { myPrograms(skip: $skip, take: $take) { ...ProgramCardFields } }
fragment OrganizationSummaryFields on ProgramOrganizationModel { id name slug }
fragment ProgramCardFields on ProgramModel { currency id organizationId organization { ...OrganizationSummaryFields } title slug description contentLocale scope rules status visibility rewardGrid rewardRange { min max currency } triageDeadlineBusinessDays startDate endDate createdAt }

query GetMySupportConversation { mySupportConversation { ...SupportConversationFields } }
fragment SupportMessageFields on SupportMessageModel { id conversationId body author { id username } authorSide createdAt redactedAt attachments { id fileName contentType fileSize fileAccess } }
fragment SupportConversationFields on SupportConversationModel { id userId user { id username email } status createdAt lastMessageAt closedAt unreadCount lastMessage { ...SupportMessageFields } }

query GetProgram($id: ID!) { program(id: $id) { ...ProgramDetailFields } }
fragment OrganizationSummaryFields on ProgramOrganizationModel { id name slug }
fragment ProgramCardFields on ProgramModel { currency id organizationId organization { ...OrganizationSummaryFields } title slug description contentLocale scope rules status visibility rewardGrid rewardRange { min max currency } triageDeadlineBusinessDays startDate endDate createdAt }
fragment ProgramDetailFields on ProgramModel { currency ...ProgramCardFields outOfScope updatedAt sentBack { reason sentAt } }

query GetProgramBySlug($slug: String!) { programBySlug(slug: $slug) { ...ProgramDetailFields } }
fragment OrganizationSummaryFields on ProgramOrganizationModel { id name slug }
fragment ProgramCardFields on ProgramModel { currency id organizationId organization { ...OrganizationSummaryFields } title slug description contentLocale scope rules status visibility rewardGrid rewardRange { min max currency } triageDeadlineBusinessDays startDate endDate createdAt }
fragment ProgramDetailFields on ProgramModel { currency ...ProgramCardFields outOfScope updatedAt sentBack { reason sentAt } }

query GetPrograms($filters: ProgramFilterInput, $skip: Int, $take: Int) { programs(filters: $filters, skip: $skip, take: $take) { ...ProgramCardFields } }
fragment OrganizationSummaryFields on ProgramOrganizationModel { id name slug }
fragment ProgramCardFields on ProgramModel { currency id organizationId organization { ...OrganizationSummaryFields } title slug description contentLocale scope rules status visibility rewardGrid rewardRange { min max currency } triageDeadlineBusinessDays startDate endDate createdAt }

query GetReportAdjudication($reportId: ID!) { reportAdjudication(reportId: $reportId) { ...AdjudicationFields } }
fragment CriticalReviewFields on CriticalReviewModel { id adjudicationId outcome reviewerId supersedingAdjudicationId createdAt }
fragment AdjudicationFields on AdjudicationModel { id reportId severity amount currency taxonomyId taxonomyVersion vrtNodeId vrtBaselinePriority deviationReason cvssVersion cvssVector cvssScore cweId amountBasis amountReason reasoning decisionVector assessorId assessorUsername side awaitingCriticalReview criticalReviewDueAt criticalReview { ...CriticalReviewFields } supersedesId createdAt }

query GetSupportConversationForUser($userId: ID!) { supportConversationForUser(userId: $userId) { ...SupportConversationFields } }
fragment SupportMessageFields on SupportMessageModel { id conversationId body author { id username } authorSide createdAt redactedAt attachments { id fileName contentType fileSize fileAccess } }
fragment SupportConversationFields on SupportConversationModel { id userId user { id username email } status createdAt lastMessageAt closedAt unreadCount lastMessage { ...SupportMessageFields } }

query GetSupportConversations($filter: SupportConversationFilterInput, $cursor: String, $take: Int) { supportConversations(filter: $filter, cursor: $cursor, take: $take) { items { ...SupportConversationFields } nextCursor } }
fragment SupportMessageFields on SupportMessageModel { id conversationId body author { id username } authorSide createdAt redactedAt attachments { id fileName contentType fileSize fileAccess } }
fragment SupportConversationFields on SupportConversationModel { id userId user { id username email } status createdAt lastMessageAt closedAt unreadCount lastMessage { ...SupportMessageFields } }

mutation ReviewCriticalGrade($input: ReviewCriticalGradeInput!) { reviewCriticalGrade(input: $input) { ...AdjudicationFields } }
fragment CriticalReviewFields on CriticalReviewModel { id adjudicationId outcome reviewerId supersedingAdjudicationId createdAt }
fragment AdjudicationFields on AdjudicationModel { id reportId severity amount currency taxonomyId taxonomyVersion vrtNodeId vrtBaselinePriority deviationReason cvssVersion cvssVector cvssScore cweId amountBasis amountReason reasoning decisionVector assessorId assessorUsername side awaitingCriticalReview criticalReviewDueAt criticalReview { ...CriticalReviewFields } supersedesId createdAt }

mutation SendProgramBackToDraft($id: ID!, $reason: String!) { sendProgramBackToDraft(id: $id, reason: $reason) { ...ProgramDetailFields } }
fragment OrganizationSummaryFields on ProgramOrganizationModel { id name slug }
fragment ProgramCardFields on ProgramModel { currency id organizationId organization { ...OrganizationSummaryFields } title slug description contentLocale scope rules status visibility rewardGrid rewardRange { min max currency } triageDeadlineBusinessDays startDate endDate createdAt }
fragment ProgramDetailFields on ProgramModel { currency ...ProgramCardFields outOfScope updatedAt sentBack { reason sentAt } }
